using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍  Researching: {topic}\n");

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
var notebook = new Notebook();
var webSearch = new WebSearchTool();

var tools = new[]
{
    AIFunctionFactory.Create(webSearch.SearchWeb),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

// ---------------------------------------------------------------------------
// Chat client with automatic function-calling
// ---------------------------------------------------------------------------
IChatClient client = new OpenAIClient(openAiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions { Tools = [.. tools] };

// ---------------------------------------------------------------------------
// Agent loop
// ---------------------------------------------------------------------------
List<ChatMessage> messages =
[
    new(ChatRole.System, """
        You are a research agent. Your job is to thoroughly research the topic
        the user provides by using your tools.

        Workflow:
        1. Search the web for relevant information (use multiple varied queries).
        2. Save important findings as notes using the note-taking tool.
        3. When you have gathered enough information, retrieve all your notes and
           write a well-structured summary with key findings and sources.

        Be thorough — issue at least 3 different search queries to cover the
        topic from multiple angles.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary:\n\n{topic}"),
];

var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n────────────────────────────────────────");
Console.WriteLine("📝  RESEARCH SUMMARY");
Console.WriteLine("────────────────────────────────────────\n");
Console.WriteLine(response.Text);
Console.WriteLine();

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input)
        ? throw new InvalidOperationException("A research topic is required.")
        : input;
}

// ---------------------------------------------------------------------------
// Web Search Tool — uses the Brave Search API (free tier) or falls back to
// a lightweight DuckDuckGo HTML scrape when BRAVE_API_KEY is not set.
// ---------------------------------------------------------------------------
sealed class WebSearchTool
{
    private readonly HttpClient _http = new();
    private readonly string? _braveKey = Environment.GetEnvironmentVariable("BRAVE_API_KEY");

    [Description("Search the web for information. Returns a list of result snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query")] string query)
    {
        Console.WriteLine($"  🌐  Searching: \"{query}\"");

        try
        {
            return _braveKey is not null
                ? await BraveSearch(query)
                : await DuckDuckGoSearch(query);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private async Task<string> BraveSearch(string query)
    {
        var request = new HttpRequestMessage(HttpMethod.Get,
            $"https://api.search.brave.com/res/v1/web/search?q={Uri.EscapeDataString(query)}&count=5");
        request.Headers.Add("X-Subscription-Token", _braveKey);
        request.Headers.Add("Accept", "application/json");

        var resp = await _http.SendAsync(request);
        resp.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(await resp.Content.ReadAsStreamAsync());
        var results = doc.RootElement.GetProperty("web").GetProperty("results");

        var lines = new List<string>();
        foreach (var r in results.EnumerateArray())
        {
            var title = r.GetProperty("title").GetString();
            var url = r.GetProperty("url").GetString();
            var snippet = r.TryGetProperty("description", out var d) ? d.GetString() : "";
            lines.Add($"- {title}\n  {url}\n  {snippet}");
        }

        return lines.Count > 0 ? string.Join("\n\n", lines) : "No results found.";
    }

    private async Task<string> DuckDuckGoSearch(string query)
    {
        var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";
        var request = new HttpRequestMessage(HttpMethod.Get, url);
        request.Headers.Add("User-Agent", "ResearchAgent/1.0");

        var resp = await _http.SendAsync(request);
        resp.EnsureSuccessStatusCode();

        var html = await resp.Content.ReadAsStringAsync();
        var snippets = ExtractDdgSnippets(html);

        return snippets.Count > 0
            ? string.Join("\n\n", snippets.Take(5))
            : "No results found.";
    }

    private static List<string> ExtractDdgSnippets(string html)
    {
        var results = new List<string>();
        var span = html.AsSpan();

        // DuckDuckGo HTML results have class="result__snippet"
        const string marker = "class=\"result__snippet\"";
        int pos = 0;
        while (pos < span.Length && results.Count < 5)
        {
            int idx = html.IndexOf(marker, pos, StringComparison.Ordinal);
            if (idx < 0) break;

            // Find the title link before the snippet
            var titleMarker = "class=\"result__a\"";
            int titleIdx = html.LastIndexOf(titleMarker, idx, StringComparison.Ordinal);
            string title = "";
            string link = "";
            if (titleIdx > 0)
            {
                int hrefStart = html.LastIndexOf("href=\"", titleIdx, StringComparison.Ordinal);
                if (hrefStart > 0)
                {
                    hrefStart += 6;
                    int hrefEnd = html.IndexOf('"', hrefStart);
                    if (hrefEnd > hrefStart)
                        link = html[hrefStart..hrefEnd];
                }

                int tagClose = html.IndexOf('>', titleIdx);
                int tagEnd = html.IndexOf("</a>", tagClose, StringComparison.Ordinal);
                if (tagClose > 0 && tagEnd > tagClose)
                    title = StripHtml(html[(tagClose + 1)..tagEnd]);
            }

            // Extract snippet text
            int start = html.IndexOf('>', idx + marker.Length);
            if (start < 0) break;
            start++;
            int end = html.IndexOf("</", start, StringComparison.Ordinal);
            if (end < 0) break;

            var snippet = StripHtml(html[start..end]).Trim();
            if (snippet.Length > 0)
                results.Add($"- {title}\n  {link}\n  {snippet}");

            pos = end;
        }

        return results;
    }

    private static string StripHtml(string html) =>
        System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", "").Trim();
}

