            int start = html.IndexOf('>', idx + marker.Length);
            if (start < 0) break;
            start++;
            int end = html.IndexOf("</", start, StringComparison.Ordinal);
            if (end < 0) break;

            var snippet = StripHtml(html[start..end]).Trim();
            if (snippet.Length > 0)
                results.Add($"- {title}\n  {link}\n  {snippet}");

